/* Lookup table for phys data */
typedef struct {
    const char *path;
    const uint8_t *data;
    size_t size;
} EmbeddedEntry;

static const EmbeddedEntry phys_entries[] = {
    { "data/collision/ball_physics_e4000.bin", phys_ball_physics_e4000, 4096 },
    { "data/collision/ball_physics_ec000.bin", phys_ball_physics_ec000, 16384 },
    { "data/collision/ball_physics_f0000.bin", phys_ball_physics_f0000, 9216 },
};

#define PHYS_COUNT (sizeof(phys_entries) / sizeof(phys_entries[0]))

const uint8_t *embedded_physics_data(const char *path, size_t *out_size) {
    for (size_t i = 0; i < PHYS_COUNT; i++) {
        if (strcmp(path, phys_entries[i].path) == 0) {
            *out_size = phys_entries[i].size;
            return phys_entries[i].data;
        }
    }
    *out_size = 0;
    return NULL;
}
